INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-sec3-a', 'The Drugs and Cosmetics Act, 1940 (Act No. 23 of 1940)', 'Section 3(a)', 'Section 3(a) - Definition of Ayurvedic, Siddha or Unani Drug', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/2366', '''Ayurvedic, Siddha or Unani drug'' includes all medicines intended for internal or external use for or in the diagnosis, treatment, mitigation or prevention of disease or disorder in human beings or animals, and manufactured exclusively in accordance with the formulae described in the authoritative books of Ayurvedic, Siddha and Unani Tibb systems of medicine, specified in the First Schedule.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-sec3-h', 'The Drugs and Cosmetics Act, 1940', 'Section 3(h)', 'Section 3(h) - Patent or Proprietary Medicine (Ayurvedic/ASU)', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/2366', 'In relation to Ayurvedic, Siddha or Unani Tibb systems of medicine, ''patent or proprietary medicine'' means a drug which is a formulation containing only ingredients mentioned in the formulae described in the authoritative books of Ayurveda, Siddha or Unani Tibb systems of medicine specified in the First Schedule, but does not include a medicine which is administered by parenteral route and also a formulation which is not specified in the First Schedule.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-first-schedule', 'The Drugs and Cosmetics Act, 1940', 'The First Schedule', 'The First Schedule - Authoritative Books of ASU Systems', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/2366', 'Specifies the 56 authoritative texts for Ayurveda including: Charaka Samhita, Sushruta Samhita, Ashtanga Hridaya, Ashtanga Samgraha, Sharangadhara Samhita, Bhaishajya Ratnavali, Chakradatta, Rasendra Sara Sangraha, Rasa Ratna Samucchaya, Sahasrayogam, Yogaratnakara, Ayurvedic Formulary of India (AFI Parts I, II, III), and Ayurvedic Pharmacopoeia of India (API). Any classical drug claiming Section 3(a) status MUST be prepared strictly according to recipes in these 56 texts.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-sec33ee', 'The Drugs and Cosmetics Act, 1940', 'Section 33EE', 'Section 33EE - Misbranded Ayurvedic Drugs', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/2366', 'An Ayurvedic drug shall be deemed to be misbranded if: (a) it is so coloured, coated, powdered or polished that damage is concealed, or if it is made to appear of better or greater therapeutic value than it really is; or (b) it is not labelled in the prescribed manner; or (c) its label or container or anything accompanying the drug bears any statement, design or device which makes any false claim for the drug or which is false or misleading in any particular.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-sec33eeb', 'The Drugs and Cosmetics Act, 1940', 'Section 33EEB', 'Section 33EEB - Spurious Ayurvedic Drugs', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/2366', 'An Ayurvedic drug shall be deemed to be spurious: (a) if it is manufactured under a name which belongs to another drug; or (b) if it is an imitation of, or a substitute for, another drug; or (c) if it purports to be the product of a manufacturer of whom it is not truly a product; or (d) if it has been substituted wholly or in part by another drug or substance.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-schedule-t', 'The Drugs and Cosmetics Rules, 1945', 'Schedule T (D&C Rules 1945)', 'Schedule T - Good Manufacturing Practices (GMP) for Ayurvedic Drugs', 'india', 'rule', 'https://cdsco.gov.in', 'Schedule T mandates factory premises, hygiene, raw material storage, machinery equipment, quality control section, raw material identification (botanical authentication, TLC fingerprinting, pesticide residue tests, heavy metals testing - Lead, Cadmium, Arsenic, Mercury), batch manufacturing records (BMR), and stability testing for all licensed ASU manufacturers in India. Non-compliance results in cancellation of manufacturing license under Rule 158.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-dca-rule-158-b', 'The Drugs and Cosmetics Rules, 1945', 'Rule 158-B (D&C Rules 1945)', 'Rule 158-B - Guidelines for Issue of License with respect to ASU Drugs', 'india', 'rule', 'https://cdsco.gov.in', 'Provides evidentiary requirements for licensing ASU drugs in India: Category 1 (Classical ASU Drugs): Proof of reference in First Schedule texts, no safety/efficacy trials needed. Category 2 (Patent or Proprietary): Category 2(A) (Ingredients from authoritative texts with same indications): Published literature on safety and evidence of efficacy. Category 2(B) (New combination with new indication): Acute/sub-acute toxicity studies, published clinical trials or pilot clinical trials. Category 2(C) (Extracts of classical plants / Purified fractions): Complete phase I/II/III toxicological and clinical trial data similar to new chemical entities.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-fssai-ayush-reg3', 'Food Safety and Standards (Ayush Aahar) Regulations, 2022', 'Regulation 3', 'Regulation 3 - Definition and Scope of Ayush Aahar', 'india', 'regulation', 'https://fssai.gov.in', '''Ayush Aahar'' means food manufactured or prepared in accordance with the recipes or books/texts specified in the First Schedule of the Drugs and Cosmetics Act, 1940, and other authoritative books of Ayurveda, Siddha and Unani specified under the regulations, including health foods, dietary supplements and functional foods prepared from botanical ingredients. Ayush Aahar does not include drugs defined under Section 3(b) or Section 3(a) of the D&C Act, nor synthetic vitamins/minerals/amino acids.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-fssai-ayush-reg5', 'Food Safety and Standards (Ayush Aahar) Regulations, 2022', 'Regulation 5', 'Regulation 5 - Prohibition of Therapeutic and Medicinal Claims', 'india', 'regulation', 'https://fssai.gov.in', 'Ayush Aahar products shall NOT claim to prevent, treat, cure, mitigate, or diagnose any specific disease or pathological condition in human beings. Permissible claims are strictly restricted to health promotion, nutritional support, physiological balance (Dosha balance), immunity enhancement, and general wellness. Any product carrying therapeutic or curative claims shall be deemed an Ayurvedic Drug and must obtain a license from State AYUSH Licensing Authorities under D&C Act 1940 instead of FSSAI.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-gi-sec2-1-e', 'The Geographical Indications of Goods (Registration and Protection) Act, 1999 (Act No. 48 of 1999)', 'Section 2(1)(e)', 'Section 2(1)(e) - Definition of Geographical Indication', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1981', '''geographical indication'', in relation to goods, means an indication which identifies such goods as agricultural goods, natural goods or manufactured goods as originating, or manufactured in the territory of a country, or a region or locality in that territory, where a given quality, reputation or other characteristic of such goods is essentially attributable to its geographical origin and in case where such goods are manufactured goods one of the activities of either the production or of processing or preparation of the goods concerned takes place in such territory, region or locality, as the case may be.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-gi-sec9', 'The Geographical Indications of Goods Act, 1999', 'Section 9', 'Section 9 - Prohibition of Registration of Certain Geographical Indications', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1981', 'A geographical indication: (a) the use of which would be likely to deceive or cause confusion; or (b) the use of which would be contrary to any law for the time being in force; or (c) which comprises or contains scandalous or obscene matter; or (d) which comprises or contains any matter likely to hurt the religious susceptibilities of any class or section of the citizens of India; or (e) which would otherwise be disentitled to protection in a court; or (f) which are determined to be generic names or indications of goods and have, therefore, ceased to be protected in their country of origin, or which have fallen into disuse in that country; or (g) which, although literally true as to the country, territory or locality in which the goods originate, falsely represent to the public that the goods originate in another territory, shall not be registered.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-gi-sec21', 'The Geographical Indications of Goods Act, 1999', 'Section 21', 'Section 21 - Rights Conferred by Registration of Geographical Indication', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1981', 'The registration of a geographical indication shall give to the registered proprietor and the authorized user the right to obtain relief in respect of infringement of the geographical indication in the manner provided by this Act; and to the authorized user thereof the exclusive right to the use of the geographical indication in relation to the goods in respect of which the geographical indication is registered.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec2-1-j', 'The Patents Act, 1970 (Act No. 39 of 1970)', 'Section 2(1)(j)', 'Section 2(1)(j) - Definition of Invention', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', '''invention'' means a new product or process involving an inventive step and capable of industrial application. For an invention to be patentable, it must satisfy three cumulative criteria: novelty (not anticipated in prior art anywhere in the world), inventive step (a feature of an invention that involves technical advance as compared to existing knowledge or having economic significance or both and that makes the invention not obvious to a person skilled in the art), and utility / industrial applicability.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-a', 'The Patents Act, 1970', 'Section 3(a)', 'Section 3(a) - Inventions contrary to natural laws or frivolous', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (a) an invention which is frivolous or which claims anything obviously contrary to well established natural laws.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-b', 'The Patents Act, 1970', 'Section 3(b)', 'Section 3(b) - Contrary to public order or morality or injurious to health', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (b) an invention the primary or intended use or commercial exploitation of which could be contrary to public order or morality or which causes serious prejudice to human, animal or plant life or health or to the environment.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-c', 'The Patents Act, 1970', 'Section 3(c)', 'Section 3(c) - Mere discovery of scientific principle or living thing', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (c) the mere discovery of a scientific principle or the formulation of an abstract theory or discovery of any living thing or non-living substance occurring in nature. Pure natural plant extracts, unisolated native phytochemicals, or naturally occurring botanical species cannot be claimed as patentable subject matter.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-d', 'The Patents Act, 1970', 'Section 3(d)', 'Section 3(d) - Mere discovery of new form of known substance without enhanced efficacy', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (d) the mere discovery of a new form of a known substance which does not result in the enhancement of the known efficacy of that substance or the mere discovery of any new property or new use for a known substance or of the mere use of a known process, machine or apparatus unless such known process results in a new product or employs at least one new reactant. Explanation.—For the purposes of this clause, salts, esters, ethers, polymorphs, metabolites, pure form, particle size, isomers, mixtures of isomers, complexes, combinations and other derivatives of known substance shall be considered to be the same substance, unless they differ significantly in properties with regard to efficacy.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-e', 'The Patents Act, 1970', 'Section 3(e)', 'Section 3(e) - Mere admixture resulting only in aggregation of properties', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (e) a substance obtained by a mere admixture resulting only in aggregation of the properties of the components thereof or a process for producing such substance. In AYUSH formulations, simply mixing two or more known herbs (e.g. Ashwagandha + Shatavari) without demonstrating unexpected synergism (synergistic ratio substantiated by experimental comparative bioassay data) falls squarely under Section 3(e) and is rejected.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-h', 'The Patents Act, 1970', 'Section 3(h)', 'Section 3(h) - Method of agriculture or horticulture', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (h) a method of agriculture or horticulture. Cultivation techniques for medicinal plants, wild harvesting protocols, or nursery propagation methods cannot be patented.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-i', 'The Patents Act, 1970', 'Section 3(i)', 'Section 3(i) - Method of treatment of human beings or animals', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (i) any process for the medicinal, surgical, curative, prophylactic, diagnostic, therapeutic or other treatment of human beings or any similar treatment of animals to render them free of disease or to increase their economic value or that of their products. Methods of treating diseases with herbal extracts or dosage regimens cannot be patented in India; only novel, synergistic compositions or novel extraction processes can be claimed.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-j', 'The Patents Act, 1970', 'Section 3(j)', 'Section 3(j) - Plants and animals in whole or any part thereof', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (j) plants and animals in whole or any part thereof other than micro-organisms, but including seeds, varieties and species and essentially biological processes for production or propagation of plants and animals. Plant varieties are protectable under the Protection of Plant Varieties and Farmers'' Rights Act, 2001 (PPVFR Act), not under the Patents Act.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec3-p', 'The Patents Act, 1970', 'Section 3(p)', 'Section 3(p) - Traditional Knowledge or aggregation/duplication thereof', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'The following are not inventions within the meaning of this Act: (p) an invention which in effect, is traditional knowledge or which is an aggregation or duplication of known properties of traditionally known component or components. Added by the Patents (Amendment) Act 2002 to codify protection of Indian traditional medicine (Ayurveda, Unani, Siddha, Sowa-Rigpa) against bio-piracy. If an ingredient or formulation is documented in the Ayurvedic Formulary of India (AFI), Ayurvedic Pharmacopoeia of India (API), Charaka Samhita, Sushruta Samhita, Ashtanga Hridaya, Sharangadhara Samhita, Bhaishajya Ratnavali, or the Traditional Knowledge Digital Library (TKDL), it is unpatentable as an invention per se under Section 3(p).');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec10-4', 'The Patents Act, 1970', 'Section 10(4)', 'Section 10(4) - Mandatory Disclosure of Biological Material Source & NBA Approval', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'Every complete specification shall: (d) disclose the source and geographical origin of the biological material in the specification, when used in an invention. If the biological material is obtained from India, the applicant must disclose the exact location and obtain prior permission from the National Biodiversity Authority (NBA) under Section 6 of the Biological Diversity Act, 2002 before the grant of the patent. Failure to disclose or wrongful disclosure of source/origin is an explicit ground for pre-grant opposition under Section 25(1)(j), post-grant opposition under Section 25(2)(j), and revocation of the patent under Section 64(1)(p).');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec25', 'The Patents Act, 1970', 'Section 25', 'Section 25 - Opposition to the Grant of Patent (Pre-grant and Post-grant)', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'Under Section 25(1), any person may file a pre-grant opposition in writing against the grant of patent on grounds including: (d) that the invention was publicly known or publicly used in India; (f) that the subject of any claim is not an invention within the meaning of this Act, or is not patentable under Section 3; (k) that the complete specification does not disclose or wrongly mentions the source or geographical origin of biological material used for the invention; (k) that the invention so far as claimed in any claim of the complete specification is anticipated having regard to the knowledge, oral or otherwise, available within any local or indigenous community in India or elsewhere. This enables TKDL and third parties to prevent illegitimate patents.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('in-patent-sec64-1-p', 'The Patents Act, 1970', 'Section 64(1)(p)', 'Section 64(1)(p) - Revocation for Non-disclosure or Anticipation by Traditional Knowledge', 'india', 'statute', 'https://www.indiacode.nic.in/handle/123456789/1392', 'A patent may be revoked on petition of any person interested or the Central Government on the grounds: (p) that the complete specification does not disclose or wrongly mentions the source or geographical origin of biological material used for the invention; (q) that the invention so far as claimed in any claim of the complete specification was anticipated having regard to the knowledge, oral or otherwise, available within any local or indigenous community in India or elsewhere.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-cbd-art8-j', 'Convention on Biological Diversity (CBD), 1992', 'Article 8(j)', 'Article 8(j) - Traditional Knowledge, Innovations and Practices', 'international', 'treaty', 'https://www.cbd.int/doc/legal/cbd-en.pdf', 'Each Contracting Party shall, as far as possible and as appropriate: Subject to its national legislation, respect, preserve and maintain knowledge, innovations and practices of indigenous and local communities embodying traditional lifestyles relevant for the conservation and sustainable use of biological diversity and promote their wider application with the approval and involvement of the holders of such knowledge, innovations and practices and encourage the equitable sharing of the benefits arising from the utilization of such knowledge, innovations and practices.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-cbd-art15', 'Convention on Biological Diversity (CBD), 1992', 'Article 15', 'Article 15 - Access to Genetic Resources and National Sovereignty', 'international', 'treaty', 'https://www.cbd.int/doc/legal/cbd-en.pdf', '1. Recognizing the sovereign rights of States over their natural resources, the authority to determine access to genetic resources rests with the national governments and is subject to national legislation. 2. Each Contracting Party shall endeavour to create conditions to facilitate access to genetic resources for environmentally sound uses by other Contracting Parties and not to impose restrictions that run counter to the objectives of this Convention. 3. For the purpose of this Convention, the genetic resources being provided by a Contracting Party are only those that are provided by Contracting Parties that are countries of origin of such resources or by the Parties that have acquired the genetic resources in accordance with this Convention. 4. Access, where granted, shall be on mutually agreed terms and subject to the provisions of this Article. 5. Access to genetic resources shall be subject to prior informed consent of the Contracting Party providing such resources, unless otherwise determined by that Party.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-nagoya-art5', 'Nagoya Protocol on Access to Genetic Resources and the Fair and Equitable Sharing of Benefits Arising from their Utilization to the Convention on Biological Diversity (2010)', 'Article 5', 'Article 5 - Fair and Equitable Benefit-Sharing', 'international', 'treaty', 'https://www.cbd.int/abs/text/', '1. In accordance with Article 15, paragraphs 3 and 7 of the Convention, benefits arising from the utilization of genetic resources as well as subsequent applications and commercialization shall be shared in a fair and equitable way with the Party providing such resources that is the country of origin of such resources or a Party that has acquired the genetic resources in accordance with the Convention. Such sharing shall be upon mutually agreed terms. 2. Each Party shall take legislative, administrative or policy measures, as appropriate, with the aim of ensuring that benefits arising from the utilization of genetic resources that are held by indigenous and local communities, in accordance with domestic legislation regarding the established rights of these indigenous and local communities over these genetic resources, are shared in a fair and equitable way with the communities concerned, based on mutually agreed terms.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-nagoya-art6', 'Nagoya Protocol, 2010', 'Article 6', 'Article 6 - Prior Informed Consent (PIC) for Access to Genetic Resources', 'international', 'treaty', 'https://www.cbd.int/abs/text/', '1. In the exercise of sovereign rights over natural resources, and subject to domestic access and benefit-sharing legislation or regulatory requirements, access to genetic resources for their utilization shall be subject to the prior informed consent of the Party providing such resources that is the country of origin of such resources or a Party that has acquired the genetic resources in accordance with the Convention, unless otherwise determined by that Party. 2. In accordance with domestic law, each Party shall take measures, as appropriate, with the aim of ensuring that the prior informed consent or approval and involvement of indigenous and local communities is obtained for access to genetic resources where they have the established right to grant access to such resources.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-nagoya-art7', 'Nagoya Protocol, 2010', 'Article 7', 'Article 7 - Access to Traditional Knowledge Associated with Genetic Resources', 'international', 'treaty', 'https://www.cbd.int/abs/text/', 'In accordance with domestic law, each Party shall take measures, as appropriate, with the aim of ensuring that traditional knowledge associated with genetic resources that is held by indigenous and local communities is accessed with the prior and informed consent or approval and involvement of these indigenous and local communities, and that mutually agreed terms have been established. This international obligation prevents foreign pharmaceutical and biotech corporations from accessing traditional indigenous remedies without explicit consent and fair financial/technological return.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-nagoya-art15-16', 'Nagoya Protocol, 2010', 'Articles 15 & 16', 'Articles 15 & 16 - Compliance with Domestic Legislation on ABS and TK', 'international', 'treaty', 'https://www.cbd.int/abs/text/', 'Each Party shall take appropriate, effective and proportionate legislative, administrative or policy measures to provide that genetic resources and traditional knowledge associated with genetic resources utilized within its jurisdiction have been accessed in accordance with prior informed consent and that mutually agreed terms have been established, as required by the domestic access and benefit-sharing legislation of the other Party. Parties shall cooperate in cases of alleged violation.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-pct-art15-33', 'Patent Cooperation Treaty (PCT), 1970 (as modified)', 'Articles 15 & 33', 'Articles 15 & 33 - International Search and International Preliminary Examination', 'international', 'treaty', 'https://www.wipo.int/pct/en/texts/', 'Article 15: Each international application shall be the subject of international search. The objective of the international search is to discover relevant prior art. The prior art shall consist of everything which has been made available to the public anywhere in the world by means of written disclosure (including patent documents, published scientific literature, and accessible traditional knowledge databases like TKDL). Article 33: The objective of international preliminary examination is to formulate a preliminary and non-binding opinion on whether the claimed invention appears to be novel, to involve an inventive step (to be non-obvious), and to be industrially applicable.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-trips-art27-1', 'Agreement on Trade-Related Aspects of Intellectual Property Rights (TRIPS), 1994', 'Article 27.1', 'Article 27.1 - Patentable Subject Matter', 'international', 'treaty', 'https://www.wto.org/english/docs_e/legal_e/27-trips_04c_e.htm#5', 'Subject to the provisions of paragraphs 2 and 3, patents shall be available for any inventions, whether products or processes, in all fields of technology, provided that they are new, involve an inventive step and are capable of industrial application. Subject to paragraph 4 of Article 65, paragraph 8 of Article 70 and paragraph 3 of this Article, patents shall be available and patent rights enjoyable without discrimination as to the place of invention, the field of technology and whether products are imported or locally produced.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-trips-art27-2', 'TRIPS Agreement, 1994', 'Article 27.2', 'Article 27.2 - Exclusions to Protect Ordre Public or Morality', 'international', 'treaty', 'https://www.wto.org/english/docs_e/legal_e/27-trips_04c_e.htm#5', 'Members may exclude from patentability inventions, the prevention within their territory of the commercial exploitation of which is necessary to protect ordre public or morality, including to protect human, animal or plant life or health or to avoid serious prejudice to the environment, provided that such exclusion is not made merely because the exploitation is prohibited by their law.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-trips-art27-3-b', 'TRIPS Agreement, 1994', 'Article 27.3(b)', 'Article 27.3(b) - Exclusions for Plants, Animals and Biological Processes', 'international', 'treaty', 'https://www.wto.org/english/docs_e/legal_e/27-trips_04c_e.htm#5', 'Members may also exclude from patentability: (a) diagnostic, therapeutic and surgical methods for the treatment of humans or animals; (b) plants and animals other than micro-organisms, and essentially biological processes for the production of plants or animals other than non-biological and microbiological processes. However, Members shall provide for the protection of plant varieties either by patents or by an effective sui generis system or by any combination thereof.');
INSERT INTO corpus_chunks (chunk_id, statute, section_or_article, title, jurisdiction, doc_type, url, text_content) VALUES ('intl-trips-art29', 'TRIPS Agreement, 1994', 'Article 29', 'Article 29 - Conditions on Patent Applicants (Sufficiency of Disclosure)', 'international', 'treaty', 'https://www.wto.org/english/docs_e/legal_e/27-trips_04c_e.htm#5', '1. Members shall require that an applicant for a patent shall disclose the invention in a manner sufficiently clear and complete for the invention to be carried out by a person skilled in the art and may require the applicant to indicate the best mode for carrying out the invention known to the inventor at the filing date or, where priority is claimed, at the priority date of the application. 2. Members may require an applicant for a patent to provide information concerning the applicant''s corresponding foreign applications and grants.');
